const items = $input.all();
const today = new Date().toISOString().split('T')[0];

// RemoteOK splits the JSON array — first item is metadata with legal-notice
const jobs = items.filter(item => !item.json['legal-notice'] && item.json.position);

return jobs.map(job => ({
  json: {
    job_title: job.json.position || '',
    company: job.json.company || '',
    job_url: job.json.url || `https://remoteok.com/l/${job.json.id}`,
    source: 'RemoteOK',
    location_text: String(job.json.location || 'Worldwide'),
    salary: job.json.salary_min ? `$${job.json.salary_min} - $${job.json.salary_max || '?'}/yr` : '',
    description: (job.json.description || '').replace(/<[^>]*>/g, ' ').slice(0, 3000),
    posted_date: job.json.date || today,
    tags: Array.isArray(job.json.tags) ? job.json.tags.join(', ') : '',
    job_id: `remoteok_${job.json.id || job.json.slug}`,
    date_found: today
  }
}));

