const items = $input.all();
const today = new Date().toISOString().split('T')[0];
const data = items[0]?.json;
let edges = [];
try {
  edges = data?.data?.jobs?.edges || data?.jobs || [];
} catch(e) { edges = []; }

return edges.map(edge => {
  const job = edge.node || edge;
  const isRemote = (job.locationPreferences || []).some(l => l.preference === 'remote' || l.preference === 'fully_remote');
  if (!isRemote && edges.length > 0) return null;
  const sal = job.salary;
  const salary = sal ? `$${sal.minimum || '?'} - $${sal.maximum || '?'} ${sal.currency || ''}` : '';
  const url = `https://app.otta.com/jobs/${job.slug || job.id}`;
  return {
    json: {
      job_title: job.title || '',
      company: job.company?.name || '',
      job_url: url,
      source: 'Otta',
      location_text: 'Remote',
      salary,
      description: (job.description || '').replace(/<[^>]*>/g, ' ').slice(0, 3000),
      posted_date: today,
      tags: (job.skills || []).map(s => s.value).join(', '),
      job_id: `otta_${job.id || job.slug}`,
      date_found: today
    }
  };
}).filter(Boolean);

const items = $input.all();

// Separate existing URLs from new jobs
const existingUrls = new Set();
const existingKeys = new Set();
const newJobs = [];

for (const item of items) {
  if (item.json._item_type === 'existing_url') {
    if (item.json.job_url) existingUrls.add(item.json.job_url.trim().toLowerCase());
    if (item.json.job_title && item.json.company) {
      existingKeys.add(`${item.json.job_title.toLowerCase()}|${item.json.company.toLowerCase()}`);
    }
  } else {
    newJobs.push(item);
  }
}

// Filter out duplicates
const seen = new Set();
const unique = [];

for (const job of newJobs) {
  const url = (job.json.job_url || '').trim().toLowerCase();
  const key = `${(job.json.job_title || '').toLowerCase()}|${(job.json.company || '').toLowerCase()}`;

  if (!url || existingUrls.has(url) || seen.has(url)) continue;
  if (existingKeys.has(key)) continue;
  if (seen.has(key)) continue;

  seen.add(url);
  seen.add(key);
  unique.push(job);
}

return unique;

const REJECT_PATTERNS = [
  /\bus\s*only\b/i, /\busa\s*only\b/i, /\bunited\s*states\s*only\b/i,
  /\bcanada\s*only\b/i, /\buk\s*only\b/i, /\bunited\s*kingdom\s*only\b/i,
  /\beu\s*only\b/i, /\beurope\s*only\b/i, /\baustralia\s*only\b/i,
  /\bmust\s*be\s*based\s*in\b/i, /\bmust\s*live\s*in\b/i,
  /\bmust\s*be\s*authorized\s*to\s*work\b/i, /\bwork\s*permit\s*required\b/i,
  /\blocal\s*work\s*permit\b/i, /\bhybrid\b/i,
  /\bonsite\b/i, /\bon-site\b/i, /\boffice\s*required\b/i,
  /\bin-office\b/i, /\bremote\s*within\s*(?:the\s*)?us\b/i,
  /\bremote\s*within\s*(?:one\s*)?country\b/i,
  /\bfixed\s*us\s*hours\b/i, /\bfixed\s*eu\s*hours\b/i,
  /\bapplicants\s*must\s*reside\b/i, /\bmust\s*reside\s*in\b/i,
  /\bcitizens\s*only\b/i, /\bgreen\s*card\b/i,
  /\bwork\s*authorization\s*required\b/i, /\bsponsorship\s*not\s*available\b/i
];

const KEEP_BOOST = [
  /worldwide\s*remote/i, /global\s*remote/i, /work\s*from\s*anywhere/i,
  /apac\s*remote/i, /international\s*contractors/i,
  /\bdeel\b/i, /remote\.com/i, /\boyster\b/i, /\beor\b/i,
  /employer\s*of\s*record/i, /remote[-\s]first/i, /fully\s*distributed/i,
  /all\s*timezones/i, /timezone\s*flexible/i, /async[-\s]first/i,
  /anywhere\s*in\s*the\s*world/i, /open\s*to\s*worldwide/i
];

const items = $input.all();
const kept = [];
const rejected = [];

for (const item of items) {
  const text = [
    item.json.description || '',
    item.json.location_text || '',
    item.json.job_title || '',
    item.json.tags || ''
  ].join(' ');

  const hasReject = REJECT_PATTERNS.some(p => p.test(text));
  const hasKeep = KEEP_BOOST.some(p => p.test(text));

  if (hasReject && !hasKeep) {
    item.json._hard_filter = 'rejected';
    item.json._reject_reason = 'keyword: geographic/authorization restriction';
    rejected.push(item);
  } else {
    item.json._hard_filter = hasKeep ? 'kept_explicit' : 'kept_unclear';
    item.json._location_boost = hasKeep;
    kept.push(item);
  }
}

return [kept, rejected];

const SYSTEM_PROMPT = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.
Do not pass the job only because it says "remote."

REJECT if the job:
- Requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan
- Requires local work authorization outside Taiwan
- Is hybrid, onsite, or remote within one country only
- Requires fixed working hours that would force Jerry to work through the night in Taiwan (PST 9-5 = midnight-8am Taiwan)

KEEP only if one of these is true:
- The job says worldwide remote, work from anywhere, or global remote
- The job says APAC remote
- The job allows international contractors
- The job accepts people based anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement

Respond with ONLY valid JSON. No explanation outside the JSON object.

Return exactly this JSON structure:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "one short sentence",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}`;

const job = $json;
const userContent = `Job Title: ${job.job_title}
Company: ${job.company}
Location Info: ${job.location_text}
Tags: ${job.tags}
Description:\n${job.description.slice(0, 2000)}`;

return [{
  json: {
    ...$json,
    _ai_request_body: JSON.stringify({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 400,
      system: SYSTEM_PROMPT,
      messages: [
        { role: 'user', content: userContent }
      ]
    })
  }
}];

const response = $json;
let aiResult = {
  taiwan_eligible: 'unclear',
  reason: 'Parse error',
  location_risk: 'high',
  timezone_risk: 'medium',
  contractor_possible: 'unclear',
  decision: 'manual_check'
};

try {
  const content = response.content?.[0]?.text || response.choices?.[0]?.message?.content || '';
  // Extract JSON block if wrapped in markdown
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiResult = JSON.parse(jsonMatch[0]);
  }
} catch(e) {
  aiResult.reason = `Parse failed: ${e.message}`;
}

// Preserve original job fields from the previous run context
// Note: the AI HTTP request loses the original json, so we carry it via headers isn't possible
// We resolve this via pairing approach — user should check this node's output
return [{
  json: {
    ...$json,
    taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
    taiwan_reason: aiResult.reason || '',
    location_risk: aiResult.location_risk || 'high',
    timezone_risk: aiResult.timezone_risk || 'medium',
    contractor_possible: aiResult.contractor_possible || 'unclear',
    ai_decision: aiResult.decision || 'manual_check'
  }
}];

// This node re-merges the AI response with the original job data.
// It pairs items from the AI check with the original job data by index.
// Both branches must have the same order of items.
const items = $input.all();

// Each item should already have both job fields and AI fields
// (because we carry original fields through the Prepare AI Request node)
// Just pass through with cleanup
return items.map(item => ({
  json: {
    date_found: item.json.date_found || new Date().toISOString().split('T')[0],
    source: item.json.source || '',
    job_title: item.json.job_title || '',
    company: item.json.company || '',
    job_url: item.json.job_url || '',
    location_text: item.json.location_text || '',
    salary: item.json.salary || '',
    description: item.json.description || '',
    posted_date: item.json.posted_date || '',
    tags: item.json.tags || '',
    job_id: item.json.job_id || '',
    taiwan_eligible: item.json.taiwan_eligible || 'unclear',
    taiwan_reason: item.json.taiwan_reason || '',
    location_risk: item.json.location_risk || 'medium',
    timezone_risk: item.json.timezone_risk || 'medium',
    contractor_possible: item.json.contractor_possible || 'unclear',
    ai_decision: item.json.ai_decision || 'manual_check',
    _location_boost: item.json._location_boost || false
  }
}));

const text = [
  $json.description || '',
  $json.tags || '',
  $json.job_title || ''
].join(' ').toLowerCase();

const ASYNC_HIGH = [
  /\basync[-\s]first\b/i, /\basynchronous\s*work/i, /\bfully\s*async\b/i,
  /\bno\s*(?:required|mandatory)\s*meetings/i, /\bwrite[-\s]first\b/i,
  /\blow\s*meeting\s*culture/i, /\bwork\s*across\s*time\s*zones/i
];

const ASYNC_MED = [
  /\bflexible\s*hours/i, /\bflexible\s*schedule/i, /\bflexuous\b/i,
  /\bdistributed\s*team/i, /\bfully\s*distributed/i,
  /\basync/i, /\basynchronous/i
];

const ASYNC_LOW_RISK = [
  /\bremote[-\s]first/i, /\bwork\s*remotely/i
];

const REJECT_ASYNC = [
  /\bstrict\s*9\s*(?:to|-)\s*5\b/i, /\bfixed\s*(?:us|est|pst|cst|cet)\s*hours/i,
  /\bdaily\s*(?:live|standups)\b/i, /\bmust\s*overlap\s*full\s*business\s*day/i,
  /\brequired\s*on\s*calls\b/i, /\bcore\s*hours\s*9/i
];

const hasRejectAsync = REJECT_ASYNC.some(p => p.test(text));
let async_level = 'low';
if (!hasRejectAsync) {
  if (ASYNC_HIGH.some(p => p.test(text))) async_level = 'high';
  else if (ASYNC_MED.some(p => p.test(text))) async_level = 'medium';
  else if (ASYNC_LOW_RISK.some(p => p.test(text))) async_level = 'low_remote';
}

return [{ json: { ...$json, async_level, _async_rejected: hasRejectAsync } }];

const text = [$json.job_title || '', $json.tags || '', $json.description?.slice(0, 500) || ''].join(' ').toLowerCase();

const ROLE_TIERS = [
  {
    category: 'data_analyst',
    patterns: [/\bdata\s*analyst\b/i, /\banalytics\s*analyst\b/i, /\bbusiness\s*analyst\b/i],
    score: 25
  },
  {
    category: 'data_scientist',
    patterns: [/\bdata\s*scientist\b/i, /\bjunior\s*data\s*scientist\b/i, /\bml\s*engineer\b/i],
    score: 25
  },
  {
    category: 'bi_analyst',
    patterns: [/\bbi\s*analyst\b/i, /\bbusiness\s*intelligence\b/i, /\btableau\b/i, /\bpower\s*bi\b/i, /\blooker\b/i],
    score: 25
  },
  {
    category: 'marketing_analyst',
    patterns: [/\bmarketing\s*analyst\b/i, /\bperformance\s*marketing\b/i, /\bgrowth\s*analyst\b/i, /\bmartech\b/i, /\bppc\b/i, /\bseo\b/i, /\bga4\b/i, /\bmeta\s*ads\b/i, /\bgoogle\s*ads\b/i],
    score: 25
  },
  {
    category: 'ai_automation',
    patterns: [/\bai\s*(?:marketing|automation|workflow|specialist|analyst)\b/i, /\bautomation\s*specialist\b/i, /\bai\s*tools\b/i, /\bprompt\s*engineer\b/i, /\bn8n\b/i, /\bmake\.com\b/i, /\bzapier\b/i],
    score: 25
  },
  {
    category: 'adjacent',
    patterns: [/\bdigital\s*marketing\b/i, /\bcontent\s*analyst\b/i, /\bcreative\s*strategist\b/i, /\bgrowth\s*hacking\b/i, /\bcrm\b/i, /\bcustomer\s*data\b/i, /\banalytics\b/i, /\breporting\b/i],
    score: 15
  }
];

let role_category = 'other';
let role_score = 0;
for (const tier of ROLE_TIERS) {
  if (tier.patterns.some(p => p.test(text))) {
    role_category = tier.category;
    role_score = tier.score;
    break;
  }
}

return [{ json: { ...$json, role_category, role_score } }];

const j = $json;
let score = 0;
const scoreBreakdown = {};

// ── TAIWAN ELIGIBILITY (40 pts max) ────────────────────────────
const te = (j.taiwan_eligible || '').toLowerCase();
const lr = (j.location_risk || 'high').toLowerCase();
const boost = j._location_boost;

if (te === 'yes' || lr === 'low' || boost) {
  scoreBreakdown.taiwan = 40;
} else if (j.ai_decision === 'manual_check' || te === 'unclear') {
  scoreBreakdown.taiwan = lr === 'medium' ? 20 : 10;
} else {
  scoreBreakdown.taiwan = 0;
}
score += scoreBreakdown.taiwan;

// ── ASYNC FIT (25 pts max) ──────────────────────────────────────
const al = (j.async_level || 'low').toLowerCase();
if (j._async_rejected) {
  scoreBreakdown.async = 0;
} else if (al === 'high') {
  scoreBreakdown.async = 25;
} else if (al === 'medium') {
  scoreBreakdown.async = 20;
} else if (al === 'low_remote') {
  scoreBreakdown.async = 10;
} else {
  scoreBreakdown.async = 5;
}
score += scoreBreakdown.async;

// ── ROLE FIT (25 pts max) ───────────────────────────────────────
scoreBreakdown.role = j.role_score || 0;
score += scoreBreakdown.role;

// ── SALARY FIT (10–25 pts) ──────────────────────────────────────
const salStr = (j.salary || '').replace(/[^0-9,]/g, '');
const salNums = salStr.match(/\d{4,}/g);
let salScore = 0;
if (salNums && salNums.length > 0) {
  const maxSal = Math.max(...salNums.map(n => parseInt(n.replace(',', ''))));
  if (maxSal >= 60000) salScore = 25;       // ≥$5k/month annualized
  else if (maxSal >= 36000) salScore = 15;  // ≥$3k/month annualized
  else salScore = 10;                       // listed but lower
} // 0 if not listed
scoreBreakdown.salary = salScore;
score += salScore;

// ── FINAL ONE-SENTENCE RULE CHECK ──────────────────────────────
const passesOneRule =
  scoreBreakdown.taiwan > 0 &&
  !j._async_rejected &&
  j.ai_decision !== 'reject' &&
  j.taiwan_eligible !== 'no';

if (!passesOneRule) score = Math.min(score, 30);

// Determine why this is a good fit
const whyFit = [];
if (te === 'yes') whyFit.push('Taiwan-confirmed');
if (boost) whyFit.push('has global/worldwide language');
if (al === 'high') whyFit.push('async-first culture');
if (al === 'medium') whyFit.push('flexible async hours');
if (j.role_category !== 'other') whyFit.push(`role: ${j.role_category.replace(/_/g, ' ')}`);
if (salScore >= 15) whyFit.push('competitive salary listed');

return [{
  json: {
    ...j,
    score: Math.min(100, Math.max(0, score)),
    score_breakdown: JSON.stringify(scoreBreakdown),
    why_good_fit: whyFit.join('; ') || 'to be reviewed',
    decision: score >= 85 ? 'apply_immediately' : score >= 70 ? 'apply_or_review' : 'reject',
    application_status: 'not_applied',
    notes: ''
  }
}];

const job = $json;
const prompt = `Write a short cover letter for Jerry.

Jerry is based in Taiwan and wants async global remote work.

Jerry's background:
- Bilingual: English (native-level, California-raised) and Mandarin Chinese
- Digital marketing background: SEO, PPC, GA4, Meta Ads, Google Ads, performance marketing
- Data science bootcamp graduate: Python, SQL, Tableau, Power BI
- AI tools experience: ChatGPT, Claude, Gemini, Cursor
- Projects: dashboards, EDA, machine learning, customer segmentation, fraud detection, marketing analytics
- Currently based in Taiwan, available for immediate start

JOB DETAILS:
Title: ${job.job_title}
Company: ${job.company}
Salary: ${job.salary || 'not listed'}
Role type: ${job.role_category?.replace(/_/g, ' ')}
Why it fits Jerry: ${job.why_good_fit}

Job description summary:
${job.description?.slice(0, 1000)}

WRITING INSTRUCTIONS:
- Under 220 words
- Tone: confident, direct, human — not desperate
- Be specific to this job and company
- Mention how Jerry can:
  * Reduce manual analysis time
