const items = $input.all();
const today = new Date().toISOString().split('T')[0];

// Separate into categories
const topJobs = items
  .filter(i => i.json.score >= 70)
  .sort((a, b) => b.json.score - a.json.score)
  .slice(0, 10);

const manualCheck = items.filter(i =>
  i.json.taiwan_eligible === 'unclear' &&
  i.json.score >= 60 &&
  i.json.location_risk !== 'high'
);

// Rejection stats
const rejected = items.filter(i => i.json.score < 70 || i.json.ai_decision === 'reject');
const stats = {
  total: items.length,
  passed: topJobs.length,
  manual: manualCheck.length,
  rejected: rejected.length,
  by_us_only: rejected.filter(i => /us only|usa only/i.test(i.json._reject_reason || '')).length,
  by_eu_only: rejected.filter(i => /eu only|europe only/i.test(i.json._reject_reason || '')).length,
  by_hybrid: rejected.filter(i => /hybrid/i.test(i.json._reject_reason || '')).length,
  by_timezone: rejected.filter(i => i.json.timezone_risk === 'high').length
};

// Build top jobs section
let topSection = '';
topJobs.forEach((item, idx) => {
  const j = item.json;
  topSection += `
${idx + 1}. ${j.job_title}
   Company: ${j.company}
   Score: ${j.score}/100
   Taiwan eligible: ${j.taiwan_eligible} — ${j.taiwan_reason}
   Async level: ${j.async_level}
   Timezone risk: ${j.timezone_risk}
   Salary: ${j.salary || 'not listed'}
   Why it fits Jerry: ${j.why_good_fit}
   Apply: ${j.job_url}
`;
});

// Manual check section
let manualSection = '';
if (manualCheck.length > 0) {
  manualSection = '\n--- MANUAL CHECK (unclear Taiwan eligibility, score ≥60) ---\n';
  manualCheck.forEach((item, idx) => {
    const j = item.json;
    manualSection += `${idx + 1}. ${j.job_title} @ ${j.company} | Score: ${j.score} | ${j.job_url}\n`;
  });
}

// Rejection summary
const rejSummary = `
--- REJECTION SUMMARY ---
Total processed: ${stats.total}
Passed (score ≥70): ${stats.passed}
Manual check: ${stats.manual}
Rejected: ${stats.rejected}
  US only: ${stats.by_us_only}
  EU only: ${stats.by_eu_only}
  Hybrid/onsite: ${stats.by_hybrid}
  High timezone risk: ${stats.by_timezone}
`;

const emailBody = `Daily Taiwan Eligible Async Remote Jobs — ${today}
${'='.repeat(50)}

Top jobs today:
${topJobs.length > 0 ? topSection : 'No jobs passed the 70-point threshold today.'}
${manualSection}
${rejSummary}

---
Powered by Taiwan Job Hunter n8n Workflow
`;

const telegramBody = `📋 *Daily Job Digest — ${today}*

✅ Passed: ${stats.passed} | 🔍 Manual: ${stats.manual} | ❌ Rejected: ${stats.rejected}

${topJobs.slice(0, 5).map((item, i) => {
  const j = item.json;
  return `${i + 1}. *${j.job_title}* @ ${j.company}\n   Score: ${j.score} | ${j.taiwan_eligible} | ${j.async_level} async\n   ${j.job_url}`;
}).join('\n\n')}

${manualCheck.length > 0 ? `🔍 ${manualCheck.length} jobs need manual Taiwan check` : ''}`;

return [{
  json: {
    email_body: emailBody,
    telegram_body: telegramBody,
    stats,
    digest_date: today,
    jobs_count: topJobs.length
  }
}];
